WITH flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time ASC, id ASC) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time ASC, id ASC) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_session FROM transactions), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY txn_type ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT s.id, s.account_id, s.txn_type, s.merchant, s.is_flagged, s.session_no, CASE WHEN txn_type RLIKE '^(DEBIT|REFUND)$' THEN 'GROUP_A' WHEN txn_type RLIKE '^(CREDIT|FEE)$' THEN 'CORE' ELSE 'GROUP_B' END AS txn_type_zone, (SELECT MIN(x.amount) FROM transactions x WHERE x.account_id = s.account_id) AS min_transaction_amount FROM islands s ORDER BY txn_type_zone DESC NULLS LAST
